```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmName ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { 
    dbr:Woman_by_Woman:_New_Hope_for_the_Villages_of_India 
    dbr:Windsor_Drive_(film) 
  }

  # film name (prefer dbp:name)
  OPTIONAL { ?film dbp:name ?filmName . }
  OPTIONAL { ?film rdfs:label ?filmName FILTER (lang(?filmName) = "en") }

  # director (prefer dbp:director, fallback to dbo:director)
  { ?film dbp:director ?director . }
  UNION
  { ?film dbo:director ?director . }

  # director name (prefer dbp:name)
  OPTIONAL { ?director dbp:name ?directorName . }
  OPTIONAL { ?director dbo:name ?directorName . }
  OPTIONAL { ?director rdfs:label ?directorName FILTER (lang(?directorName) = "en") }

  # director birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
}
LIMIT 100
```

